contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint minSum, uint deposit, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= minSum);
        require(amount <= balBefore);
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        assert(reverted ? (balAfter == balBefore && ethAfter == ethBefore)
                        : (balAfter == balBefore - amount && ethAfter == ethBefore - amount));
    }
    receive() external payable {}
}

