pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 minSum, uint256 deposit, uint256 amount) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(balBefore >= minSum);
        vm.assume(amount <= balBefore);
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        assertTrue(reverted ? (balAfter == balBefore && ethAfter == ethBefore)
                        : (balAfter == balBefore - amount && ethAfter == ethBefore - amount));
    }

    function testFuzz_run(uint256 minSum, uint256 deposit, uint256 amount) public {
        _run(minSum, deposit, amount);
    }

    receive() external payable {}
}
